// Journée en cours : toutes les 15 min en semaine (8h-19h45) -> aujourd'hui seulement.
// Passage de 19h25 (tous les jours) : hier + aujourd'hui (rattrape les trajets faits après 19h25 la veille).
// Rattrapage manuel : les 45 derniers jours.
const it = $input.first().json || {};
const auto = !!(it.timestamp || it['Readable date']);
const now = DateTime.now().setZone('Europe/Paris');
const soir = now.hour === 19 && now.minute >= 20 && now.minute < 30;
const n = !auto ? 45 : (soir ? 2 : 1);
const jours = [];
for (let i = n - 1; i >= 0; i--) jours.push(now.minus({ days: i }).toISODate());
return [{ json: { jours, mode: !auto ? 'rattrapage' : (soir ? 'soir' : 'journee') } }];

// Historique Quartix (LECTURE SEULE) : une ligne par jour et par véhicule dans la table quartix_jours.
// Pour chaque jour : trajets (heures, lieux, km, durée, tracé GPS simplifié) + arrêts entre les trajets.
// L'authentification est faite par le nœud « Auth Quartix » (identifiant n8n chiffré).
// Chaque arrêt est rattaché à l'intervention ou au RDV Interfast du jour le plus proche (< 350 m), adresse géocodée par la Géoplateforme (BAN),
// avec repli sur la table clients_gps. Arrêt sans RDV = « hors intervention ». Dépôt et maison de Laurent reconnus à la distance.
const r = $('Auth Quartix').first().json || {};
const jours = $('Jours a lire').first().json.jours || [];
const b = r.body || {};
const d = b.Data || b.data || {};
const tok = d.AccessToken || d.accessToken;
const maintenant = DateTime.now().setZone('Europe/Paris').toISO();
if (!tok) {
  return [{ json: { jour: '_bilan', immat: '_bilan', journal_json: JSON.stringify({ erreur: 'Connexion Quartix refusée', code: r.statusCode || null }), maj: maintenant } }];
}
const base = 'https://qws.quartix.net/v2/api';
const H = { AccessToken: tok };
const get = async (p) => { const x = await this.helpers.httpRequest({ method: 'GET', url: base + p, headers: H, json: true, timeout: 30000 }); return x && (x.Data || x.data); };
// Lecture insensible à la casse (Quartix répond en PascalCase, la doc montre du camelCase)
const g = (o, k) => { if (!o) return undefined; if (o[k] !== undefined) return o[k]; const K = k.toLowerCase(); for (const n of Object.keys(o)) if (n.toLowerCase() === K) return o[n]; return undefined; };
const lieu = s => String(s || '').replace(/, France$/, '').trim();
const estDepot = s => /^climatpro$/i.test(String(s || '').trim()) || /Chem(in|\.) de Dandon/i.test(String(s || ''));
const jourParis = iso => DateTime.fromISO(String(iso), { setZone: true }).setZone('Europe/Paris').toISODate();
const dist = (a, c) => { const R = 6371000, t = Math.PI / 180; const dLa = (c[0] - a[0]) * t, dLo = (c[1] - a[1]) * t; const x = Math.sin(dLa / 2) ** 2 + Math.cos(a[0] * t) * Math.cos(c[0] * t) * Math.sin(dLo / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(x)); };
// ---------- Interventions et RDV Interfast (sous-workflow Interfast - Lecture, lecture seule) ----------
const evParJour = {};
const vusEv = new Set();
for (const n of ['Interventions du jour', 'RDV du jour']) {
  let L = []; try { L = $(n).all(); } catch (e) { L = []; }
  for (const it of L) {
    const items = (it.json && it.json.ok && it.json.data && it.json.data.items) || [];
    for (const ev of items) {
      if (!ev || vusEv.has(String(ev.id)) || ev.lifecycleState === 'cancelled' || ev.category === 'task') continue;
      vusEv.add(String(ev.id));
      const j = ev.dateParis || (ev.start ? DateTime.fromISO(ev.start, { zone: 'utc' }).setZone('Europe/Paris').toISODate() : null);
      if (!j) continue;
      (evParJour[j] = evParJour[j] || []).push(ev);
    }
  }
}
const gpsClient = {};
try { for (const it of $('Lire clients_gps').all()) { const c = it.json || {}; if (c.client_id && typeof c.lat === 'number') gpsClient[String(c.client_id)] = { lat: c.lat, lon: c.lon, adresse: c.adresse }; } } catch (e) {}
const sGeo = $getWorkflowStaticData('global');
sGeo.geo = sGeo.geo || {};
if (Object.keys(sGeo.geo).length > 3000) sGeo.geo = {}; // cache des géocodages, vidé s'il devient trop gros
let nbGeo = 0, geoKo = 0;
const geocoder = async (adr) => {
  const k = String(adr || '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (!k) return null;
  if (sGeo.geo[k] !== undefined) return sGeo.geo[k];
  let res = null;
  for (const url of ['https://data.geopf.fr/geocodage/search?limit=1&q=', 'https://api-adresse.data.gouv.fr/search/?limit=1&q=']) {
    try {
      const x = await this.helpers.httpRequest({ method: 'GET', url: url + encodeURIComponent(k), json: true, timeout: 10000 });
      const f = x && x.features && x.features[0];
      if (f && f.geometry && f.properties && f.properties.score >= 0.5) res = { lat: f.geometry.coordinates[1], lon: f.geometry.coordinates[0], score: Math.round(f.properties.score * 100) / 100, type: f.properties.type || '' };
      nbGeo++;
      break;
    } catch (e) { geoKo++; }
  }
  sGeo.geo[k] = res;
  return res;
};
const posEv = async (ev) => {
  const g1 = ev.address ? await geocoder(ev.address) : null;
  if (g1) return g1;
  const c = ev.client && gpsClient[String(ev.client.id)];
  return c ? { lat: c.lat, lon: c.lon, score: null, type: 'clients_gps' } : null;
};
// Comparaison d'adresses en texte (repli quand le géocodage est approximatif) : même code postal + même nom de voie
const sansAccent = x => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const ABR = [[/\brte\b/g, 'route'], [/\bav\b\.?/g, 'avenue'], [/\bbd\b/g, 'boulevard'], [/\bchem\b\.?/g, 'chemin'], [/\bimp\b\.?/g, 'impasse'], [/\bdom\b\.?/g, 'domaine'], [/\ballee\b/g, 'allee'], [/\bst\b/g, 'saint']];
const voie = adr => {
  let t = sansAccent(adr).replace(/[.,]/g, ' ');
  for (const [re, v] of ABR) t = t.replace(re, v);
  const cp = (t.match(/\b(\d{5})\b/) || [])[1] || '';
  const m = t.replace(/\b\d{5}\b.*$/, '').match(/^\s*\d+\s*(bis|ter)?\s+(.+?)\s*$/);
  const nom = (m ? m[2] : t.replace(/\b\d{5}\b.*$/, '')).replace(/\s+-\s+.*$/, '').replace(/\s+/g, ' ').trim();
  return { cp, nom, num: m ? parseInt(t.match(/^\s*(\d+)/)[1], 10) : null };
};
// Les numeros doivent etre proches : <= 150 en numerotation metrique (>= 1000, ex. 6933 / 6963), <= 10 sinon
const memeVoie = (a, b) => {
  const x = voie(a), y = voie(b);
  if (!(x.cp && x.cp === y.cp && x.nom && x.nom.length > 4 && x.nom === y.nom && x.num && y.num)) return false;
  return Math.abs(x.num - y.num) <= (Math.max(x.num, y.num) >= 1000 ? 150 : 10);
};
const DEPOT = [43.5788, 6.95012], MAISON = [43.57814, 6.96076];
// Lieux connus (fournisseurs) : adresse geocodee une fois puis gardee en cache. A completer au fil de l'eau.
const LIEUX = [
  { nom: 'Sonepar', role: 'fournisseur', adresse: '4 avenue du Centre 06150 Cannes', rayon: 90 },
  { nom: 'La Plateforme du Bâtiment', role: 'fournisseur', adresse: '51 avenue des Arlucs 06150 Cannes', rayon: 90 }
];
for (const l of LIEUX) { const p = await geocoder(l.adresse); if (p) { l.lat = p.lat; l.lon = p.lon; } }
const TYPE = ev => String(ev.title && ev.title !== ev.type ? ev.title : (ev.type || (ev.category === 'meeting' ? 'Rendez-vous' : 'Intervention'))).replace(/\s+/g, ' ').trim().slice(0, 80);
let nbRattaches = 0, nbArrets = 0;
const vehicules = (await get('/vehicles')) || [];
const out = [];
const erreurs = [];
let exemple = null;
const debut = Date.now();
let interrompu = null;
for (const jour of jours) {
  if (Date.now() - debut > 240000) { interrompu = jour; break; } // limite de durée d'un nœud Code : relancer pour la suite
  const evsJour = [];
  for (const ev of (evParJour[jour] || [])) { const p = await posEv(ev); if (p) evsJour.push({ ev, p }); }
  for (const v of vehicules) {
    const vid = g(v, 'VehicleId');
    const immat = g(v, 'RegistrationNumber');
    let data;
    try { data = await get('/vehicles/route?VehicleId=' + vid + '&StartDay=' + jour + '&EndDay=' + jour); }
    catch (e) { erreurs.push(jour + ' ' + immat + ' : ' + String((e && e.message) || e).slice(0, 120)); continue; }
    const brut = (g(data, 'Trips') || []).filter(t => jourParis(g(t, 'StartDateTime')) === jour)
      .sort((a, c) => String(g(a, 'StartDateTime')).localeCompare(String(g(c, 'StartDateTime'))));
    if (!exemple && brut.length) {
      const t0 = brut[0]; const p0 = (g(t0, 'Route') || [])[0];
      exemple = { champsTrajet: Object.keys(t0), champsPoint: p0 ? Object.keys(p0) : null, nbPoints: (g(t0, 'Route') || []).length };
    }
    const T = brut.filter(t => (g(t, 'Distance') || 0) >= 0.15); // micro-déplacements (< 150 m) ignorés : ils ne coupent pas un arrêt
    if (!T.length) continue;
    const trajets = T.map(t => {
      const pts = [];
      for (const p of (g(t, 'Route') || [])) {
        const la = g(p, 'Latitude'), lo = g(p, 'Longitude');
        if (typeof la !== 'number' || typeof lo !== 'number' || (!la && !lo)) continue;
        const q = [Math.round(la * 1e5) / 1e5, Math.round(lo * 1e5) / 1e5];
        if (!pts.length || dist(pts[pts.length - 1], q) >= 40) pts.push(q);
      }
      const dep = g(t, 'StartDateTime'), arr = g(t, 'EndDateTime');
      return {
        dep, arr, de: lieu(g(t, 'StartLocation')), a: lieu(g(t, 'EndLocation')),
        deLat: g(t, 'StartLat'), deLon: g(t, 'StartLong'), aLat: g(t, 'EndLat'), aLon: g(t, 'EndLong'),
        km: Math.round((g(t, 'Distance') || 0) * 10) / 10,
        min: Math.max(0, Math.round((Date.parse(arr) - Date.parse(dep)) / 60000)),
        trace: pts
      };
    });
    const total = trajets.reduce((s, t) => s + t.trace.length, 0);
    if (total > 2500) { const pas = Math.ceil(total / 2500); trajets.forEach(t => { t.trace = t.trace.filter((_, i) => i % pas === 0 || i === t.trace.length - 1); }); }
    const arrets = [];
    for (let i = 0; i < trajets.length; i++) {
      const a = trajets[i], n = trajets[i + 1];
      const min = n ? Math.round((Date.parse(n.dep) - Date.parse(a.arr)) / 60000) : null;
      if (min !== null && min < 5) continue; // arrêts de moins de 5 min ignorés
      const pt = [a.aLat, a.aLon];
      const depot = estDepot(a.a) || (typeof a.aLat === 'number' && dist(pt, DEPOT) < 200);
      const maison = !depot && typeof a.aLat === 'number' && dist(pt, MAISON) < 200;
      const st = { lieu: a.a, lat: a.aLat, lon: a.aLon, arrivee: a.arr, depart: n ? n.dep : null, minutes: min, depot, maison, type: depot ? 'depot' : maison ? 'maison' : 'autre', client: null };
      if (st.type === 'autre' && typeof a.aLat === 'number') {
        // le lieu connu le plus proche (meme adresse = prioritaire) ; Sonepar et la Plateforme du Batiment sont a ~110 m l'un de l'autre
        let l = null, lb = Infinity;
        for (const x of LIEUX) {
          const dx = memeVoie(a.a, x.adresse) ? 0 : (x.lat ? dist(pt, [x.lat, x.lon]) : Infinity);
          if (dx <= (x.rayon || 150) && dx < lb) { l = x; lb = dx; }
        }
        if (l) { st.type = l.role; st.lieuNom = l.nom; }
      }
      if (st.type === 'autre' && typeof a.aLat === 'number') {
        nbArrets++;
        let best = null;
        for (const c of evsJour) {
          const dd = dist(pt, [c.p.lat, c.p.lon]);
          const precis = c.p.type === 'housenumber' && (c.p.score || 0) >= 0.7;
          const texte = memeVoie(a.a, c.ev.address);
          if (!(dd <= 350 || (!precis && dd <= 800) || texte)) continue;
          const ecart = Math.abs(Date.parse(c.ev.start) - Date.parse(a.arr)) / 60000;
          const note = (texte ? Math.min(dd, 50) : dd) + ecart; // le plus proche en distance (adresse identique = tres proche), puis en heure
          if (!best || note < best.note) best = { c, dd, note };
        }
        if (best) {
          const ev = best.c.ev;
          st.type = 'client';
          st.client = { nom: (ev.client && ev.client.name) || '', id: ev.client ? String(ev.client.id) : null, evId: String(ev.id), objet: TYPE(ev), adresse: String(ev.address || '').trim(), prevu: ev.heureParis || null, techniciens: ev.technicianIds || [], rdv: ev.category === 'meeting', distance: Math.round(best.dd), parTexte: best.dd > 350 };
          nbRattaches++;
        }
      }
      arrets.push(st);
    }
    const journal = {
      jour, immat, nom: g(v, 'Description'),
      km: Math.round(trajets.reduce((s, t) => s + t.km, 0) * 10) / 10,
      conduiteMin: trajets.reduce((s, t) => s + t.min, 0),
      trajets, arrets
    };
    out.push({ json: { jour, immat, journal_json: JSON.stringify(journal), maj: maintenant } });
  }
}
// Ligne de contrôle (lue par Claude, ignorée par la page)
out.push({ json: { jour: '_bilan', immat: '_bilan', journal_json: JSON.stringify({ jours: jours.length, du: jours[0], au: jours[jours.length - 1], lignes: out.length, interrompuA: interrompu, arretsHorsDepot: nbArrets, rattaches: nbRattaches, evenementsInterfast: vusEv.size, geocodages: nbGeo, geocodagesKo: geoKo, erreurs: erreurs.slice(0, 20), nbErreurs: erreurs.length, exemple }), maj: maintenant } });
return out;
